import itertools
import math

def is_square(k):
    if k < 0:
        return False
    sqrt_k = int(math.isqrt(k))
    return sqrt_k * sqrt_k == k

def check_permutation(p):
    """Checks if a given permutation p results in no partial sums being a perfect square."""
    current_sum = 0
    for x in p:
        current_sum += x
        if is_square(current_sum):
            return False  # Found a square sum
    return True  # All partial sums are not squares

def is_cool(n):
    """Checks if n is a cool integer."""
    if n == 0:
        return False

    elements = range(1, n + 1)

    # Check all permutations
    for p in itertools.permutations(elements):
        if check_permutation(p):
            # Found at least one valid permutation
            return True

    # No permutation worked
    return False

# Find the first 15 cool integers up to N=15
cool_integers = []
limit = 15
for n in range(1, limit + 1):
    if is_cool(n):
        cool_integers.append(n)

print(f"Cool integers up to {limit}: {cool_integers}")
print(f"Number of cool integers found: {len(cool_integers)}")

