import math

def is_square(n):
    if n < 1:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def solve_cool(n):
    """
    Searches for a valid permutation of (1, ..., n) using backtracking.
    Returns the permutation list if found, otherwise None.
    """
    total_sum = n * (n + 1) // 2
    if is_square(total_sum):
        return None # Guaranteed non-cool

    # State: (current_path, used_mask, current_sum)

    def backtrack(path, used_mask, current_sum):
        if len(path) == n:
            return path # Success!

        for next_num in range(1, n + 1):
            if not (used_mask & (1 << (next_num - 1))):
                next_sum = current_sum + next_num

                if not is_square(next_sum):
                    # Try this path
                    new_path = path + [next_num]
                    new_mask = used_mask | (1 << (next_num - 1))

                    result = backtrack(new_path, new_mask, next_sum)

                    if result is not None:
                        return result # Propagate success
        return None # Failure from this state

    return backtrack([], 0, 0)

# Test cases requested
N_values = [11, 12, 13]
results = {}

for N in N_values:
    print(f"--- Searching for N={N} ---")
    permutation = solve_cool(N)
    if permutation:
        print(f"Found cool permutation for N={N}: {permutation}")
        # Verification check for the found permutation
        prefix_sums = []
        current_sum = 0
        for x in permutation:
            current_sum += x
            prefix_sums.append(current_sum)

        is_valid = all(not is_square(s) for s in prefix_sums)
        print(f"Verification successful: {is_valid}")
    else:
        print(f"N={N} is likely not cool or search timed out/failed.")

